  0 < name < 2 ^ 64 -> 0x10000 <= F -> F + 512 < 0x6c0000 -> 0 <= fb < 256 -> Z.land fb 1 = 0 ->
  wrA M (s - 368) 368 ->
  cellA M 0x160bf8 8 0x1f99a0 -> cellA M 0x1f99a0 8 4096 -> cellA M 0x160c08 8 F -> cellA M (F + 260) 1 fb ->
